#!/usr/bin/env node

import {
  readFile,
  readdir,
  writeFile,
} from 'node:fs/promises';
import path from 'node:path';

const contentDirectory = path.resolve('apps/website/content');
const generatedFile = path.resolve('apps/website/models/tagInventory.generated.ts');
const registryFile = path.resolve('apps/website/models/TagRegistry.data.ts');
const writeInventory = process.argv.includes('--write');
const checkInventory = process.argv.includes('--check');
const registrySource = await readFile(registryFile, 'utf8');

const normalize = (input) => input
  .normalize('NFKD')
  .replaceAll(/[\u{0300}-\u{036F}]/gu, '')
  .toLowerCase()
  .replaceAll(/[^a-z0-9]+/g, '-')
  .replaceAll(/^-+|-+$/g, '');

const registryEntries = [...registrySource.matchAll(
  /^\s{2}(?:'([^']+)'|([a-z][a-z0-9]*)):\s*\{([\s\S]*?)^\s{2}\},?$/gm,
)];
const registeredTags = new Set(registryEntries.map((match) => match[1] ?? match[2]));
const aliases = new Map();
for (const match of registryEntries) {
  const id = match[1] ?? match[2];
  const namespace = id.includes(':') ? id.split(':', 1)[0] : undefined;
  const aliasList = /aliases:\s*\[([^\]]+)\]/.exec(match[3])?.[1] ?? '';
  for (const alias of aliasList.matchAll(/'([^']+)'/g)) {
    aliases.set(`${namespace ?? ''}:${normalize(alias[1])}`, id);
  }
}

const tagId = (namespace, value) => {
  const segment = normalize(value);
  const directId = namespace ? `${namespace}:${segment}` : segment;
  return registeredTags.has(directId)
    ? directId
    : aliases.get(`${namespace ?? ''}:${segment}`) ?? directId;
};

const yearFromDate = (value) => {
  const year = /\b(?:19|20)\d{2}\b/.exec(value)?.[0];
  return year ? Number(year) : undefined;
};

async function getFiles(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const nestedFiles = await Promise.all(entries.map(async (entry) => {
    const entryPath = path.join(directory, entry.name);
    return entry.isDirectory() ? getFiles(entryPath) : [entryPath];
  }));
  return nestedFiles.flat();
}

function add(counts, id) {
  if (id && !id.endsWith(':')) {
    counts.set(id, (counts.get(id) ?? 0) + 1);
  }
}

function addYearRange(counts, from, to) {
  const fromYear = yearFromDate(from);
  if (!fromYear) {
    return;
  }
  const toYear = yearFromDate(to) ?? new Date().getFullYear();
  for (let year = fromYear; year <= toYear; year += 1) {
    add(counts, `year:${year}`);
  }
}

function scanContent(content, counts) {
  for (const match of content.matchAll(/^#{2,4} !!skill[ \t]+(.+)$/gm)) {
    add(counts, tagId('skills', match[1]));
  }
  for (const match of content.matchAll(/^#### !tag[ \t]+(.+)$/gm)) {
    add(counts, tagId(undefined, match[1]));
  }
  const featuredCount = content.match(/^#### !featured[ \t]*$/gm)?.length ?? 0;
  for (let index = 0; index < featuredCount; index += 1) {
    add(counts, 'featured');
  }
  for (const match of content.matchAll(/^export const company = ['"]([^'"]*)['"]$/gm)) {
    if (match[1].trim()) {
      add(counts, tagId('org', match[1]));
    }
  }
  for (const match of content.matchAll(
    /^#### !from[ \t]*(.*)$[\s\S]*?^#### !to[ \t]*(.*)$/gm,
  )) {
    addYearRange(counts, match[1], match[2]);
  }
  for (const match of content.matchAll(/^#### !year[ \t]+(.+)$/gm)) {
    addYearRange(counts, match[1], match[1]);
  }
}

function generatedSource(tags) {
  const values = tags.map((id) => `  '${id}',`).join('\n');
  return '// Generated by yarn tags:inventory --write. Do not edit manually.\n'
    + `export const observedTags = [\n${values}\n] as const;\n\n`
    + 'export type ObservedTagId = typeof observedTags[number];\n';
}

const files = (await getFiles(contentDirectory)).filter((file) => (
  file.endsWith('.mdx') && !file.endsWith('.ro.mdx')
));
const counts = new Map();
for (const file of files) {
  scanContent(await readFile(file, 'utf8'), counts);
}

const tags = [...counts.keys()].toSorted((left, right) => left.localeCompare(right));
const source = generatedSource(tags);
let existingSource = '';
try {
  existingSource = await readFile(generatedFile, 'utf8');
} catch (error) {
  if (error.code !== 'ENOENT') {
    throw error;
  }
}

if (writeInventory) {
  await writeFile(generatedFile, source);
  process.stdout.write(`Wrote ${tags.length} observed tags.\n`);
} else if (checkInventory && existingSource !== source) {
  process.stderr.write('Tag inventory is stale. Run yarn tags:inventory --write.\n');
  process.exitCode = 1;
}

const collisionGroups = Map.groupBy(tags, (id) => id.replaceAll(/[^a-z0-9]/g, ''));
for (const ids of collisionGroups.values()) {
  if (ids.length > 1) {
    process.stdout.write(`collision: ${ids.join(', ')}\n`);
  }
}

for (const [id, count] of counts) {
  if (count === 1) {
    process.stdout.write(`singleton: ${id}\n`);
  }
}

for (const id of tags) {
  if (!registeredTags.has(id)) {
    process.stdout.write(`unregistered: ${id}\n`);
  }
}

if (!writeInventory && !checkInventory) {
  process.stdout.write(`Observed ${tags.length} tags across ${files.length} source files.\n`);
}
